APP("peak_shift", "Peak Shift", "Run things when power is cheap, and cut the standby", "House & Home", ["#F9A825", "#1A237E", "#00BFA5"], "bolt",
 "Peak Shift works out what each appliance really costs to run, builds a daily plan to shift washing, dishwashing, charging and heating into off-peak or solar hours, checks whether a time-of-use tariff would pay, and hunts down phantom standby loads.",
 "You are a pragmatic home-energy analyst: every claim comes with a kWh number, you respect that people won't rewire their lives, and you never sell gadgets.",
 "Same life, cheaper hours", "Your tariff and appliances make the numbers real.", ["Cost per cycle for every appliance", "A daily shift plan", "Standby hunt with payback"],
 [CH("tariff", "Tariff type", ["Flat rate", "Off-peak / night rate", "Time-of-use (several bands)", "Solar at home", "Solar + battery"]), TXT("rates", "Your rates", "peak 32p, off-peak 9p 00:00–07:00"), CH("home", "Household", ["1–2 people", "Family", "Shared house"])],
 [T("cost", "What does it cost to run?", "Wattage or rating plate → cost per use", "🔌", [PHOTO("Photo of the rating plate or energy label"), TXT("appliance", "Appliance and use", "tumble dryer, 5 loads a week; or 2000W kettle", True)],
    "Using the photo if given and '{appliance}' with the profile rates: kv (power draw kW, energy per use kWh, cost per use at peak, cost per use off-peak, cost per year at current use), a table (Alternative | kWh per use | Saving per year) such as heat-pump dryer, airing rack or eco mode, and a callout on the assumptions made about wattage and cycle length.", "kv, table, callout", "Calculate", "Reading watts…"),
  T("plan", "Shift my day", "When to run everything for the cheapest day", "🕛", [LONG("loads", "What runs in a typical day", "dishwasher nightly, washing 4x/week, EV charge 20kWh Tue/Thu, immersion heater, gaming PC evenings")],
    "Build a load-shifting plan for the profile tariff for: {loads}. Table (Appliance | Run at | Delay-start setting | Weekly kWh | Weekly cost now | After shift), kv (weekly saving, yearly saving, what can't move), steps to set delay timers and smart plugs once, and a callout on fire safety for running appliances overnight (dryers, dishwashers, chargers).", "table, kv, steps, callout", "Shift it", "Moving loads…"),
  T("tariff", "Would a different tariff pay?", "Time-of-use, EV or solar-export tariffs", "📊", [TXT("usage", "Usage and habits", "3,400 kWh/yr, EV, home in evenings, could shift washing", True), TXT("offer", "Tariff you're considering", "peak 35p 4–7pm, off-peak 12p overnight, same standing charge")],
    "Compare the profile's current tariff with '{offer}' for: {usage}. Table (Scenario | Annual cost current | Annual cost new | Difference) for 'no change in habits', 'shift the easy loads' and 'shift everything possible', kv (break-even share of usage off-peak, biggest lever), bullets on the questions to ask before switching (exit fees, smart-meter requirement, price-cap rules), and a callout stating the estimate assumptions.", "table, kv, bullets, callout", "Compare", "Crunching bands…"),
  T("standby", "Standby hunt", "Find the phantom loads worth killing", "👻", [LONG("devices", "Devices left plugged in", "TV + soundbar, 2 consoles, router, printer, phone chargers, coffee machine on clock")],
    "Estimate standby for: {devices}. Table (Device | Standby W est. | Cost per year | Kill it? yes / no / smart plug), kv (total standby cost per year, saving if the yes-items are switched off, payback on a smart plug strip), a checklist of what to switch off tonight, and a callout on what must stay on (router if needed, fridge, boiler controls, security).", "table, kv, checklist, callout", "Hunt", "Chasing ghosts…"),
  T("solar", "Use my own solar", "Self-consumption with or without a battery", "☀️", [TXT("system", "System and export rate", "4kW panels, export 15p, no battery", True), TXT("day", "Tomorrow's forecast", "sunny until 3pm, cloudy after")],
    "For '{system}' with forecast '{day}': steps for tomorrow's running order timed to the sun (washing, dishwasher, immersion, EV, cooking), a table (Hour | Expected generation kW est. | Run this), kv (self-consumption % achievable, value of export versus using it yourself), and a callout on whether a battery or diverter would pay for this setup with a rough payback range.", "steps, table, kv, callout", "Plan tomorrow", "Watching the sky…")],
 "Estimates only; check figures with your supplier and meter, and never modify wiring or overload sockets — use a qualified electrician.")

APP("ethos_invest", "Ethos Invest", "Invest in line with your values, without the jargon", "Finance", ["#004D40", "#C0CA33", "#5E35B1"], "scale",
 "Ethos Invest helps beginners invest by their values: a values screen you can actually apply, greenwash checks on fund marketing, a test of whether a fund's holdings pass your screen, a plan for switching your bank and pension, and plain-English answers to the hard questions.",
 "You are an ethical-investing educator: neutral on which values are right, rigorous about fees and tracking difference, sceptical of marketing labels, and never recommending specific securities.",
 "Money that matches your values", "Your priorities set the screen; we'll keep the finance plain.", ["A values screen you can apply", "Greenwash and holdings checks", "Bank and pension switch plan"],
 [NAME, CH("care", "Care most about", ["Climate", "Animal welfare", "Weapons & tobacco", "Human rights & labour", "Faith-based screening", "Community & local impact"], multi=True), CH("stage", "Investing stage", ["Not started", "Have a pension only", "Some funds", "Experienced"]), CH("region", "Region", ["UK", "EU", "US", "Australia", "Other"])],
 [T("screen", "Build my values screen", "Exclusions, inclusions, dealbreakers", "🧭", [LONG("values", "In your own words", "no fossil fuels or weapons, OK with banks if they lend to renewables, prefer companies paying a living wage")],
    "Turn '{values}' plus the profile's priorities into an investable screen: table (Theme | Exclude | Tolerate with limits | Actively seek), kv (screening approach that fits: negative, best-in-class, impact or engagement), bullets on the trade-offs (diversification, fees, tracking difference), and a callout on values that are hard to screen for in practice and why.", "table, kv, bullets, callout", "Build screen", "Weighing values…"),
  T("greenwash", "Greenwash check", "Photo or paste → what it really commits to", "🔍", [PHOTO("Photo or screenshot of the fund page, label or advert"), LONG("text", "Or paste the wording", "'Sustainable Global Equity… integrates ESG factors…'", False)],
    "Check the fund marketing from the photo and/or: {text} against the profile's priorities. Table (Claim made | What it actually commits to | Greenwash risk low/med/high | Question to ask), kv (labelling approach: exclusion, best-in-class, impact, engagement or 'ESG integration' only; exclusions actually listed; overall greenwash score out of 10), bullets on the weasel words spotted, and a callout on why 'ESG integration' alone rarely changes what a fund holds.", "table, kv, bullets, callout", "Check it", "Reading small print…"),
  T("holdings", "Does it pass my screen?", "Top holdings → what clashes with your values", "🧾", [LONG("holdings", "Top holdings or companies", "Apple 5%, Microsoft 4%, Shell 2%, Nestlé 1.5%…"), TXT("fund", "Fund or account name", "workplace pension default fund")],
    "Test the holdings of '{fund}': {holdings} against the profile's priorities. Table (Holding | Weight | Passes? yes / grey / no | Concern | Where to verify), kv (weight that fails, weight in a grey area, biggest single conflict, verdict: keep / tolerate / look elsewhere), bullets on the options (accept, engage via the provider, choose a screened alternative), and a callout that holdings lists are snapshots and sector labels hide subsidiaries.", "table, kv, bullets, callout", "Test holdings", "Checking names…"),
  T("switch", "Move my bank & pension", "Where your money already sits", "🏦", [TXT("current", "Current bank and pension", "high-street bank current account, workplace pension in the default fund", True)],
    "For: {current} in the profile region — steps to check where the pension default is invested and how to switch to an ethical option within the same scheme, a checklist for switching banks with minimal disruption, a table (Money pot | How to check its ethics | Effort | Impact), and a callout on not losing employer contributions, guarantees or protection when moving.", "steps, checklist, table, callout", "Plan switch", "Following the money…"),
  T("ask", "Hard questions", "Does it even work? Do I lose returns?", "❓", [CH("question", "Question", ["Does ethical investing actually change anything?", "Will I earn less?", "Is divestment or engagement better?", "Are ESG ratings reliable?", "What about my cash savings?"], "Will I earn less?")],
    "Answer '{question}' for a beginner in the profile region: text with the balanced evidence in plain English, bullets of the strongest points on each side, kv (what the evidence says, what's uncertain, what you can control), and a quote with a one-sentence takeaway.", "text, bullets, kv, quote", "Answer", "Thinking it through…")],
 "Educational only, not financial advice; investments can fall in value, and you should consider a regulated adviser before acting.")
